// ── Vietnamese Cuisine Data ────────────────────────────────────────────────
const vietnameseCuisineData = [
// ── APPETIZERS ─────────────────────────────────────────────────────────────
{ dish_name:"Goi Cuon (Fresh Spring Rolls)", state:"Vietnam", cuisine:"Vietnamese", category:"Appetizers", difficulty_level:"Easy", prep_time_minutes:30, cook_time_minutes:10, total_time_minutes:40, servings:4, short_description:"Vietnam's iconic fresh spring rolls — rice paper filled with prawns, pork, vermicelli, herbs and lettuce, served with peanut dipping sauce. Fresh, light and utterly delicious.", ingredients:[{name:"Rice paper wrappers",quantity:"16",unit:"pieces"},{name:"Cooked prawns",quantity:"200",unit:"g"},{name:"Pork belly",quantity:"150",unit:"g"},{name:"Rice vermicelli",quantity:"100",unit:"g"},{name:"Lettuce",quantity:"8",unit:"leaves"},{name:"Fresh mint",quantity:"1",unit:"bunch"},{name:"Bean sprouts",quantity:"100",unit:"g"},{name:"Peanut butter",quantity:"4",unit:"tbsp"},{name:"Hoisin sauce",quantity:"3",unit:"tbsp"},{name:"Lime juice",quantity:"2",unit:"tbsp"}], preparation_steps:["Cook pork belly until tender. Cool and slice thinly.","Cook vermicelli, rinse under cold water.","Briefly dip rice paper in warm water until just pliable.","Lay on flat surface. Place lettuce, vermicelli, pork, prawn, mint and sprouts.","Fold sides in and roll tightly.","Make peanut sauce: blend peanut butter, hoisin, lime juice and warm water.","Serve rolls immediately with peanut sauce."], chef_notes:"Rice paper must be dipped briefly — too long and it becomes too soft to roll. Roll firmly but not so tight the filling tears through. Eat immediately or cover with damp cloth.", serving_suggestions:"Serve immediately with peanut dipping sauce and extra herbs on the side.", nutrition_estimate:{calories:"225",protein_g:"14",carbohydrates_g:"28",fat_g:"7"}, tags:["Fresh","Healthy","Spring Rolls","Vietnamese"], img:"/images/vietnamese/appetizers/goi-cuon-fresh-spring-rolls-vietnamese.jpg" },
{ dish_name:"Cha Gio (Fried Spring Rolls)", state:"Vietnam", cuisine:"Vietnamese", category:"Appetizers", difficulty_level:"Medium", prep_time_minutes:40, cook_time_minutes:15, total_time_minutes:55, servings:4, short_description:"Crispy Vietnamese fried spring rolls stuffed with pork, glass noodles, mushrooms and vegetables — golden, crunchy and irresistible with nuoc cham dipping sauce.", ingredients:[{name:"Rice paper wrappers",quantity:"16",unit:"pieces"},{name:"Ground pork",quantity:"300",unit:"g"},{name:"Glass noodles",quantity:"50",unit:"g"},{name:"Wood ear mushrooms",quantity:"30",unit:"g"},{name:"Carrot",quantity:"1",unit:"medium"},{name:"Shallots",quantity:"3",unit:"pieces"},{name:"Fish sauce",quantity:"2",unit:"tbsp"},{name:"Black pepper",quantity:"0.5",unit:"tsp"},{name:"Egg",quantity:"1",unit:"large"},{name:"Oil for frying",quantity:"2",unit:"cups"}], preparation_steps:["Soak noodles and mushrooms. Drain and chop finely.","Mix pork, noodles, mushrooms, carrot, shallots, fish sauce, pepper and egg.","Briefly dip rice paper in water. Place filling near one edge.","Roll tightly, tucking in sides.","Deep fry at 170°C until golden and crispy — about 5 minutes.","Drain on wire rack.","Serve with nuoc cham dipping sauce."], chef_notes:"Vietnamese cha gio uses rice paper, not wheat wrappers — this creates uniquely crispy, bubbly texture. Fry in batches to maintain oil temperature.", serving_suggestions:"Serve wrapped in lettuce leaves with fresh herbs and nuoc cham.", nutrition_estimate:{calories:"285",protein_g:"16",carbohydrates_g:"24",fat_g:"14"}, tags:["Fried","Crispy","Street Food","Vietnamese"], img:"/images/vietnamese/appetizers/cha-gio-fried-spring-rolls-vietnamese.jpg" },
{ dish_name:"Banh Xeo (Sizzling Crepes)", state:"Vietnam", cuisine:"Vietnamese", category:"Appetizers", difficulty_level:"Medium", prep_time_minutes:20, cook_time_minutes:20, total_time_minutes:40, servings:4, short_description:"Vietnam's spectacular sizzling crepe — a turmeric-yellow rice flour pancake stuffed with pork, prawns and bean sprouts, eaten wrapped in lettuce with fresh herbs.", ingredients:[{name:"Rice flour",quantity:"200",unit:"g"},{name:"Turmeric powder",quantity:"1",unit:"tsp"},{name:"Coconut milk",quantity:"200",unit:"ml"},{name:"Water",quantity:"150",unit:"ml"},{name:"Pork belly slices",quantity:"200",unit:"g"},{name:"Prawns",quantity:"150",unit:"g"},{name:"Bean sprouts",quantity:"200",unit:"g"},{name:"Spring onion",quantity:"4",unit:"stalks"},{name:"Lettuce",quantity:"1",unit:"head"},{name:"Fresh herbs assorted",quantity:"1",unit:"bunch"}], preparation_steps:["Make batter: mix rice flour, turmeric, coconut milk and water until smooth.","Rest batter 30 minutes.","Cook pork and prawns separately. Season.","Heat pan with oil until very hot — it must sizzle when batter hits.","Pour thin layer of batter, swirl to coat pan.","Add pork, prawns and bean sprouts on one half.","Cover and cook 3 minutes until edges are crispy.","Fold in half and serve immediately."], chef_notes:"The sizzle when batter hits the pan is what gives banh xeo its name. Maximum heat creates the crispy, lacy edges. Thin batter is essential — thick batter makes a doughy crepe.", serving_suggestions:"Tear into pieces and wrap in lettuce with herbs. Dip in nuoc cham.", nutrition_estimate:{calories:"285",protein_g:"16",carbohydrates_g:"30",fat_g:"12"}, tags:["Crepe","Sizzling","Turmeric","Vietnamese"], img:"/images/vietnamese/appetizers/banh-xeo-sizzling-crepes-vietnamese.jpg" },
{ dish_name:"Banh Cuon (Steamed Rice Rolls)", state:"Vietnam", cuisine:"Vietnamese", category:"Appetizers", difficulty_level:"Hard", prep_time_minutes:30, cook_time_minutes:30, total_time_minutes:60, servings:4, short_description:"Delicate steamed rice rolls filled with seasoned pork and wood ear mushrooms, drizzled with fried shallots and served with nuoc cham — a beloved Vietnamese breakfast.", ingredients:[{name:"Rice flour",quantity:"200",unit:"g"},{name:"Tapioca flour",quantity:"30",unit:"g"},{name:"Water",quantity:"500",unit:"ml"},{name:"Ground pork",quantity:"200",unit:"g"},{name:"Wood ear mushrooms",quantity:"30",unit:"g"},{name:"Shallots",quantity:"4",unit:"pieces"},{name:"Fish sauce",quantity:"3",unit:"tbsp"},{name:"Black pepper",quantity:"0.5",unit:"tsp"},{name:"Fried shallots",quantity:"3",unit:"tbsp"},{name:"Bean sprouts",quantity:"100",unit:"g"}], preparation_steps:["Mix rice flour and tapioca flour with water into very thin batter.","Soak mushrooms, drain and chop. Cook with pork, fish sauce and pepper.","Steam very thin layer of batter on oiled cloth over boiling water — 1 minute.","Carefully slide cooked sheet off and add filling.","Roll gently into cylinder.","Top with fried shallots and serve with nuoc cham and bean sprouts."], chef_notes:"Banh cuon requires a special steaming cloth technique. The rice sheet must be paper-thin and cooked in seconds. This is one of Vietnam's most technically demanding dishes.", serving_suggestions:"Serve immediately topped with fried shallots and crispy cha lua pork sausage.", nutrition_estimate:{calories:"245",protein_g:"12",carbohydrates_g:"36",fat_g:"7"}, tags:["Steamed","Delicate","Breakfast","Vietnamese"], img:"/images/vietnamese/appetizers/banh-cuon-steamed-rice-rolls-vietnamese.jpg" },
{ dish_name:"Nem Nuong (Grilled Pork Skewers)", state:"Vietnam", cuisine:"Vietnamese", category:"Appetizers", difficulty_level:"Medium", prep_time_minutes:30, cook_time_minutes:15, total_time_minutes:45, servings:4, short_description:"Fragrant grilled pork patties on skewers with lemongrass and garlic — eaten wrapped in rice paper with fresh herbs. A beloved central Vietnamese street food.", ingredients:[{name:"Ground pork",quantity:"400",unit:"g"},{name:"Lemongrass",quantity:"2",unit:"stalks"},{name:"Garlic",quantity:"4",unit:"cloves"},{name:"Shallots",quantity:"3",unit:"pieces"},{name:"Fish sauce",quantity:"2",unit:"tbsp"},{name:"Sugar",quantity:"1",unit:"tbsp"},{name:"Baking powder",quantity:"0.5",unit:"tsp"},{name:"Rice paper",quantity:"12",unit:"pieces"},{name:"Fresh herbs",quantity:"1",unit:"bunch"},{name:"Bamboo skewers",quantity:"12",unit:"pieces"}], preparation_steps:["Finely mince lemongrass, garlic and shallots.","Mix with pork, fish sauce, sugar and baking powder.","Knead until sticky. Refrigerate 30 minutes.","Mould around skewers into elongated patties.","Grill over charcoal or high heat 4 minutes per side.","Brush with oil while grilling.","Serve with rice paper, fresh herbs and dipping sauce."], chef_notes:"Baking powder makes the pork patties slightly bouncy and helps them stay juicy. Lemongrass must be very finely minced to avoid stringy texture.", serving_suggestions:"Wrap in rice paper with herbs and rice vermicelli. Dip in nuoc cham.", nutrition_estimate:{calories:"265",protein_g:"22",carbohydrates_g:"14",fat_g:"14"}, tags:["Grilled","Pork","Lemongrass","Central Vietnam"], img:"/images/vietnamese/appetizers/nem-nuong-grilled-pork-skewers-vietnamese.jpg" },
{ dish_name:"Banh Mi (Vietnamese Sandwich)", state:"Vietnam", cuisine:"Vietnamese", category:"Appetizers", difficulty_level:"Easy", prep_time_minutes:20, cook_time_minutes:10, total_time_minutes:30, servings:4, short_description:"The world's greatest sandwich — a crispy French baguette filled with pate, Vietnamese cold cuts, pickled vegetables, fresh coriander and chilli. A perfect fusion of French and Vietnamese.", ingredients:[{name:"Vietnamese baguette",quantity:"4",unit:"pieces"},{name:"Pork pate",quantity:"100",unit:"g"},{name:"Cha lua (pork sausage)",quantity:"200",unit:"g"},{name:"Daikon radish",quantity:"150",unit:"g"},{name:"Carrot",quantity:"1",unit:"medium"},{name:"Rice vinegar",quantity:"3",unit:"tbsp"},{name:"Sugar",quantity:"2",unit:"tbsp"},{name:"Cucumber",quantity:"1",unit:"medium"},{name:"Fresh coriander",quantity:"1",unit:"bunch"},{name:"Bird's eye chilli",quantity:"4",unit:"pieces"},{name:"Mayonnaise",quantity:"4",unit:"tbsp"}], preparation_steps:["Quick-pickle daikon and carrot: julienne and soak in vinegar and sugar 30 minutes.","Warm baguette until exterior is crispy.","Spread pate on one side, mayonnaise on other.","Layer with cha lua slices.","Add pickled vegetables, cucumber slices.","Top with coriander and sliced chilli.","Press together and serve immediately."], chef_notes:"The Vietnamese baguette is lighter and crispier than French bread — the airy crumb holds the fillings without becoming soggy. The contrast of pate richness with pickled vegetables is the genius.", serving_suggestions:"Eat immediately while bread is crispy. Wrap in paper as a street food.", nutrition_estimate:{calories:"385",protein_g:"18",carbohydrates_g:"48",fat_g:"14"}, tags:["Sandwich","French-Vietnamese","Street Food","Fusion"], img:"/images/vietnamese/appetizers/banh-mi-vietnamese-sandwich-vietnamese.jpg" },
{ dish_name:"Bun Cha (Grilled Pork with Noodles)", state:"Vietnam", cuisine:"Vietnamese", category:"Appetizers", difficulty_level:"Medium", prep_time_minutes:30, cook_time_minutes:20, total_time_minutes:50, servings:4, short_description:"Hanoi's most iconic dish — grilled pork patties and belly in a sweet-sour nuoc cham broth, served alongside rice noodles and a mountain of fresh herbs.", ingredients:[{name:"Pork belly",quantity:"300",unit:"g"},{name:"Ground pork",quantity:"200",unit:"g"},{name:"Rice vermicelli",quantity:"200",unit:"g"},{name:"Fish sauce",quantity:"4",unit:"tbsp"},{name:"Sugar",quantity:"3",unit:"tbsp"},{name:"Lime juice",quantity:"3",unit:"tbsp"},{name:"Garlic",quantity:"4",unit:"cloves"},{name:"Bird's eye chilli",quantity:"3",unit:"pieces"},{name:"Shallots",quantity:"3",unit:"pieces"},{name:"Fresh herbs assorted",quantity:"1",unit:"bunch"}], preparation_steps:["Slice pork belly thinly. Marinate with fish sauce, sugar and shallots.","Form ground pork into small patties with fish sauce.","Grill both over charcoal until charred and fragrant.","Make dipping broth: diluted fish sauce with sugar, lime, garlic and chilli.","Place grilled pork in individual bowls of broth.","Cook vermicelli. Rinse and serve alongside.","Serve with giant platter of fresh herbs."], chef_notes:"Charcoal grilling is essential for authentic bun cha — the smoky char is the defining flavour. Dip the noodles and herbs into the broth with each bite.", serving_suggestions:"Serve pork in broth bowls alongside noodles and herbs. Dip noodles into broth.", nutrition_estimate:{calories:"385",protein_g:"28",carbohydrates_g:"38",fat_g:"14"}, tags:["Hanoi","Grilled Pork","Noodles","Famous"], img:"/images/vietnamese/appetizers/bun-cha-grilled-pork-noodles-vietnamese.jpg" },
{ dish_name:"Banh Khot (Mini Coconut Pancakes)", state:"Vietnam", cuisine:"Vietnamese", category:"Appetizers", difficulty_level:"Medium", prep_time_minutes:20, cook_time_minutes:20, total_time_minutes:40, servings:4, short_description:"Tiny, crispy-based coconut rice pancakes topped with a whole prawn — a southern Vietnamese speciality served with fresh lettuce and herbs.", ingredients:[{name:"Rice flour",quantity:"150",unit:"g"},{name:"Coconut milk",quantity:"200",unit:"ml"},{name:"Turmeric",quantity:"0.5",unit:"tsp"},{name:"Spring onion",quantity:"3",unit:"stalks"},{name:"Whole prawns",quantity:"16",unit:"small"},{name:"Mung bean",quantity:"50",unit:"g"},{name:"Fish sauce",quantity:"2",unit:"tbsp"},{name:"Lettuce",quantity:"1",unit:"head"},{name:"Fresh herbs",quantity:"1",unit:"bunch"},{name:"Oil",quantity:"3",unit:"tbsp"}], preparation_steps:["Mix rice flour, coconut milk, turmeric and spring onion into batter.","Soak and cook mung beans until soft.","Heat special banh khot pan or mini muffin pan.","Oil each cavity. Pour batter to fill halfway.","Place one prawn and some mung bean on top.","Cover and cook 4-5 minutes until base is crispy.","Remove and serve with lettuce and herbs."], chef_notes:"The base must be genuinely crispy — this requires good heat and adequate oil. The contrast of crispy base and soft coconut centre is what makes banh khot special.", serving_suggestions:"Wrap in lettuce with herbs. Dip in nuoc cham.", nutrition_estimate:{calories:"205",protein_g:"10",carbohydrates_g:"28",fat_g:"7"}, tags:["Coconut Pancake","Southern Vietnam","Prawn","Mini"], img:"/images/vietnamese/appetizers/banh-khot-mini-coconut-pancakes-vietnamese.jpg" },
{ dish_name:"Com Chien (Vietnamese Fried Rice)", state:"Vietnam", cuisine:"Vietnamese", category:"Appetizers", difficulty_level:"Easy", prep_time_minutes:10, cook_time_minutes:15, total_time_minutes:25, servings:4, short_description:"Vietnamese fried rice with egg, vegetables and soy sauce — lighter and simpler than Chinese fried rice, with a distinctly Vietnamese character from fish sauce.", ingredients:[{name:"Cold cooked jasmine rice",quantity:"600",unit:"g"},{name:"Eggs",quantity:"3",unit:"large"},{name:"Spring onion",quantity:"4",unit:"stalks"},{name:"Garlic",quantity:"3",unit:"cloves"},{name:"Fish sauce",quantity:"2",unit:"tbsp"},{name:"Soy sauce",quantity:"1",unit:"tbsp"},{name:"White pepper",quantity:"0.5",unit:"tsp"},{name:"Oil",quantity:"3",unit:"tbsp"},{name:"Lime",quantity:"2",unit:"pieces"},{name:"Cucumber",quantity:"1",unit:"medium"}], preparation_steps:["Heat wok until smoking. Add oil.","Fry garlic briefly. Add cold rice.","Stir-fry vigorously on high heat.","Push rice aside. Scramble eggs in pan.","Mix eggs with rice.","Season with fish sauce, soy and white pepper.","Add spring onion and toss.","Serve with lime, cucumber and extra fish sauce."], chef_notes:"Fish sauce instead of salt is what gives Vietnamese fried rice its distinctive umami character. Day-old rice is essential. Serve with a squeeze of lime.", serving_suggestions:"Serve with cucumber slices, lime and fried egg on top.", nutrition_estimate:{calories:"345",protein_g:"12",carbohydrates_g:"56",fat_g:"9"}, tags:["Fried Rice","Quick","Everyday","Vietnamese"], img:"/images/vietnamese/appetizers/com-chien-vietnamese-fried-rice-vietnamese.jpg" },
{ dish_name:"Nuoc Cham (Vietnamese Dipping Sauce)", state:"Vietnam", cuisine:"Vietnamese", category:"Appetizers", difficulty_level:"Easy", prep_time_minutes:10, cook_time_minutes:0, total_time_minutes:10, servings:8, short_description:"Vietnam's essential dipping sauce — a perfectly balanced blend of fish sauce, lime juice, sugar, garlic and chilli. The soul of Vietnamese cuisine in a small bowl.", ingredients:[{name:"Fish sauce",quantity:"4",unit:"tbsp"},{name:"Lime juice",quantity:"4",unit:"tbsp"},{name:"Sugar",quantity:"3",unit:"tbsp"},{name:"Water",quantity:"4",unit:"tbsp"},{name:"Garlic",quantity:"3",unit:"cloves"},{name:"Bird's eye chilli",quantity:"2",unit:"pieces"},{name:"Carrot",quantity:"0.25",unit:"medium"}], preparation_steps:["Dissolve sugar in warm water completely.","Add fish sauce and lime juice.","Taste — should be equally salty, sour and sweet.","Mince garlic finely. Slice chilli into rounds.","Add garlic and chilli to sauce.","Julienne carrot into tiny strips and add.","Let rest 10 minutes for flavours to meld.","Adjust balance to taste."], chef_notes:"Nuoc cham must be perfectly balanced — no single flavour should dominate. Taste constantly and adjust. Fresh lime juice is essential — bottled lime juice ruins it.", serving_suggestions:"Serve alongside virtually every Vietnamese dish as a dipping sauce.", nutrition_estimate:{calories:"35",protein_g:"1",carbohydrates_g:"8",fat_g:"0"}, tags:["Dipping Sauce","Essential","Vietnamese","Condiment"], img:"/images/vietnamese/appetizers/nuoc-cham-vietnamese-dipping-sauce-vietnamese.jpg" },
// ── SOUPS ───────────────────────────────────────────────────────────────────
{ dish_name:"Pho Bo (Beef Noodle Soup)", state:"Vietnam", cuisine:"Vietnamese", category:"Soups", difficulty_level:"Hard", prep_time_minutes:30, cook_time_minutes:360, total_time_minutes:390, servings:6, short_description:"Vietnam's most iconic dish — a crystal clear, deeply aromatic beef broth simmered for 6+ hours with charred ginger and spices, served with rice noodles and paper-thin beef.", ingredients:[{name:"Beef marrow bones",quantity:"1.5",unit:"kg"},{name:"Beef brisket",quantity:"500",unit:"g"},{name:"Ginger",quantity:"100",unit:"g"},{name:"Onion",quantity:"2",unit:"large"},{name:"Star anise",quantity:"6",unit:"pieces"},{name:"Cinnamon sticks",quantity:"2",unit:"pieces"},{name:"Cloves",quantity:"5",unit:"pieces"},{name:"Fish sauce",quantity:"4",unit:"tbsp"},{name:"Rock sugar",quantity:"30",unit:"g"},{name:"Pho noodles",quantity:"400",unit:"g"},{name:"Beef sirloin",quantity:"300",unit:"g"},{name:"Bean sprouts",quantity:"200",unit:"g"},{name:"Fresh basil",quantity:"1",unit:"bunch"},{name:"Lime",quantity:"4",unit:"pieces"}], preparation_steps:["Char ginger and onion directly over flame until blackened outside.","Blanch bones in boiling water 10 minutes. Rinse thoroughly.","Dry-toast spices until fragrant.","Simmer bones with charred aromatics and spices 5-6 hours.","Add brisket in last 2 hours.","Strain broth. Season with fish sauce and rock sugar.","Cook noodles. Slice brisket thinly. Slice raw sirloin paper-thin.","Fill bowls with noodles. Ladle boiling broth over raw beef — it cooks instantly.","Serve with sprouts, basil, lime and chilli."], chef_notes:"Charring the ginger and onion is non-negotiable — it creates the distinctive smoky-sweet depth of pho. Skim constantly during simmering for a clear broth. Never rush pho.", serving_suggestions:"Serve with a platter of sprouts, basil, lime, chilli and hoisin sauce.", nutrition_estimate:{calories:"385",protein_g:"32",carbohydrates_g:"42",fat_g:"10"}, tags:["Pho","National Dish","6-Hour Broth","Iconic"], img:"/images/vietnamese/soups/pho-bo-beef-noodle-soup-vietnamese.jpg" },
{ dish_name:"Pho Ga (Chicken Noodle Soup)", state:"Vietnam", cuisine:"Vietnamese", category:"Soups", difficulty_level:"Medium", prep_time_minutes:20, cook_time_minutes:120, total_time_minutes:140, servings:4, short_description:"The lighter, equally aromatic chicken version of Vietnam's national soup — a golden, crystal-clear chicken broth with the same warming spices as pho bo.", ingredients:[{name:"Whole chicken",quantity:"1.5",unit:"kg"},{name:"Ginger",quantity:"60",unit:"g"},{name:"Onion",quantity:"1",unit:"large"},{name:"Star anise",quantity:"4",unit:"pieces"},{name:"Cinnamon stick",quantity:"1",unit:"piece"},{name:"Fish sauce",quantity:"3",unit:"tbsp"},{name:"Rock sugar",quantity:"20",unit:"g"},{name:"Pho noodles",quantity:"300",unit:"g"},{name:"Spring onion",quantity:"4",unit:"stalks"},{name:"Coriander",quantity:"1",unit:"bunch"},{name:"Bean sprouts",quantity:"150",unit:"g"}], preparation_steps:["Char ginger and onion over flame.","Blanch chicken briefly. Rinse.","Simmer chicken with charred aromatics and spices 1.5 hours.","Remove chicken. Shred meat from bones.","Strain broth and season with fish sauce and rock sugar.","Cook noodles. Place in bowls with shredded chicken.","Ladle hot broth over.","Top with spring onion, coriander and bean sprouts."], chef_notes:"Pho ga broth should be golden and clear — not cloudy. The chicken fat gives it a silkier texture than beef pho. Remove the chicken when just cooked to keep it tender.", serving_suggestions:"Serve with lime, chilli, basil and hoisin like beef pho.", nutrition_estimate:{calories:"325",protein_g:"28",carbohydrates_g:"38",fat_g:"8"}, tags:["Pho","Chicken","Lighter","Vietnamese"], img:"/images/vietnamese/soups/pho-ga-chicken-noodle-soup-vietnamese.jpg" },
{ dish_name:"Bun Bo Hue (Spicy Beef Noodle Soup)", state:"Vietnam", cuisine:"Vietnamese", category:"Soups", difficulty_level:"Hard", prep_time_minutes:30, cook_time_minutes:180, total_time_minutes:210, servings:4, short_description:"Central Vietnam's bold, spicy answer to pho — a lemongrass-scented beef broth with shrimp paste and chilli, served with thick round noodles and tender beef shank.", ingredients:[{name:"Beef shank",quantity:"600",unit:"g"},{name:"Pork trotters",quantity:"2",unit:"pieces"},{name:"Lemongrass",quantity:"4",unit:"stalks"},{name:"Shrimp paste (mam ruoc)",quantity:"2",unit:"tbsp"},{name:"Chilli oil",quantity:"2",unit:"tbsp"},{name:"Fish sauce",quantity:"4",unit:"tbsp"},{name:"Sugar",quantity:"1",unit:"tbsp"},{name:"Bun bo hue noodles",quantity:"400",unit:"g"},{name:"Spring onion",quantity:"4",unit:"stalks"},{name:"Banana blossom",quantity:"200",unit:"g"},{name:"Bean sprouts",quantity:"150",unit:"g"}], preparation_steps:["Simmer beef shank and pork trotters 2.5 hours.","Bruise lemongrass and add in final hour.","Mix shrimp paste with warm water and add to broth.","Season with fish sauce, sugar and chilli oil.","Cook noodles separately.","Slice beef shank thinly.","Fill bowls with noodles and beef.","Ladle spicy broth over. Top with spring onion."], chef_notes:"Shrimp paste (mam ruoc) is the defining ingredient of bun bo hue — its pungent fermented flavour is irreplaceable. The broth should be spicy, savoury and deeply lemongrass-scented.", serving_suggestions:"Serve with shredded banana blossom, bean sprouts, lime and fresh herbs.", nutrition_estimate:{calories:"425",protein_g:"32",carbohydrates_g:"44",fat_g:"14"}, tags:["Hue","Spicy","Lemongrass","Central Vietnam"], img:"/images/vietnamese/soups/bun-bo-hue-spicy-beef-noodle-soup-vietnamese.jpg" },
{ dish_name:"Canh Chua (Sweet and Sour Soup)", state:"Vietnam", cuisine:"Vietnamese", category:"Soups", difficulty_level:"Easy", prep_time_minutes:20, cook_time_minutes:20, total_time_minutes:40, servings:4, short_description:"Southern Vietnam's beloved sweet and sour fish soup with pineapple, tomatoes and tamarind — a beautiful balance of sour, sweet and savoury that sings with freshness.", ingredients:[{name:"Catfish or white fish",quantity:"400",unit:"g"},{name:"Pineapple",quantity:"200",unit:"g"},{name:"Tomatoes",quantity:"2",unit:"large"},{name:"Bean sprouts",quantity:"150",unit:"g"},{name:"Taro stem",quantity:"100",unit:"g"},{name:"Tamarind paste",quantity:"3",unit:"tbsp"},{name:"Fish sauce",quantity:"3",unit:"tbsp"},{name:"Sugar",quantity:"2",unit:"tbsp"},{name:"Okra",quantity:"6",unit:"pieces"},{name:"Fresh herbs",quantity:"1",unit:"bunch"}], preparation_steps:["Bring water to boil. Add tamarind paste, fish sauce and sugar.","Add pineapple chunks and tomatoes.","Add taro stem and okra.","Gently add fish pieces — cook 5 minutes only.","Add bean sprouts at the very end.","Adjust sour-sweet-salty balance.","Top with fried garlic oil.","Garnish with rice paddy herbs and sawtooth coriander."], chef_notes:"The balance of tamarind sour, pineapple sweet and fish sauce salt must be perfect. Add bean sprouts at the end — they should remain crunchy. Never overcook the fish.", serving_suggestions:"Serve with rice as part of a Vietnamese family meal.", nutrition_estimate:{calories:"185",protein_g:"22",carbohydrates_g:"16",fat_g:"4"}, tags:["Sweet and Sour","Southern Vietnam","Fish","Tamarind"], img:"/images/vietnamese/soups/canh-chua-sweet-sour-soup-vietnamese.jpg" },
{ dish_name:"Mien Ga (Glass Noodle Chicken Soup)", state:"Vietnam", cuisine:"Vietnamese", category:"Soups", difficulty_level:"Easy", prep_time_minutes:15, cook_time_minutes:60, total_time_minutes:75, servings:4, short_description:"A light, nourishing Vietnamese chicken soup with glass noodles, mushrooms and ginger — simple, delicate and deeply comforting.", ingredients:[{name:"Whole chicken",quantity:"1",unit:"kg"},{name:"Glass noodles",quantity:"150",unit:"g"},{name:"Wood ear mushrooms",quantity:"30",unit:"g"},{name:"Ginger",quantity:"30",unit:"g"},{name:"Spring onion",quantity:"4",unit:"stalks"},{name:"Fish sauce",quantity:"3",unit:"tbsp"},{name:"Salt",quantity:"0.5",unit:"tsp"},{name:"White pepper",quantity:"0.5",unit:"tsp"},{name:"Fried shallots",quantity:"3",unit:"tbsp"}], preparation_steps:["Simmer chicken with ginger 45 minutes until tender.","Remove chicken, shred meat and discard skin.","Soak glass noodles and mushrooms. Drain.","Add mushrooms to broth. Simmer 5 minutes.","Season with fish sauce and salt.","Add glass noodles and cook 2 minutes.","Add shredded chicken.","Serve topped with spring onion, fried shallots and white pepper."], chef_notes:"Glass noodles absorb broth quickly — add them last and serve immediately. Fried shallots are essential for the authentic Vietnamese flavour.", serving_suggestions:"Serve in deep bowls topped with fried shallots and white pepper.", nutrition_estimate:{calories:"285",protein_g:"24",carbohydrates_g:"28",fat_g:"8"}, tags:["Glass Noodles","Chicken","Comforting","Vietnamese"], img:"/images/vietnamese/soups/mien-ga-glass-noodle-chicken-soup-vietnamese.jpg" },
{ dish_name:"Sup Mang Cua (Crab and Asparagus Soup)", state:"Vietnam", cuisine:"Vietnamese", category:"Soups", difficulty_level:"Easy", prep_time_minutes:15, cook_time_minutes:20, total_time_minutes:35, servings:4, short_description:"Vietnam's elegant banquet soup — a silky, golden crab and asparagus soup thickened with egg whites. A French-Vietnamese fusion beloved at celebrations.", ingredients:[{name:"Crab meat",quantity:"300",unit:"g"},{name:"Canned asparagus",quantity:"400",unit:"g"},{name:"Chicken stock",quantity:"800",unit:"ml"},{name:"Egg whites",quantity:"3",unit:"large"},{name:"Tapioca starch",quantity:"2",unit:"tbsp"},{name:"Fish sauce",quantity:"2",unit:"tbsp"},{name:"Salt",quantity:"0.5",unit:"tsp"},{name:"White pepper",quantity:"0.5",unit:"tsp"},{name:"Spring onion",quantity:"3",unit:"stalks"},{name:"Coriander",quantity:"4",unit:"sprigs"}], preparation_steps:["Bring stock to boil.","Add asparagus pieces and crab meat.","Mix tapioca starch with cold water.","Slowly pour starch mixture into simmering soup while stirring.","Beat egg whites until frothy. Pour in thin stream while stirring.","Season with fish sauce, salt and pepper.","Serve topped with spring onion and coriander."], chef_notes:"The egg white creates the characteristic silky, slightly gelatinous texture. Pour it in a thin stream while stirring constantly for delicate wisps throughout.", serving_suggestions:"Serve as an elegant starter at Vietnamese celebrations and banquets.", nutrition_estimate:{calories:"145",protein_g:"18",carbohydrates_g:"10",fat_g:"3"}, tags:["Crab","Asparagus","Banquet","Elegant"], img:"/images/vietnamese/soups/sup-mang-cua-crab-asparagus-soup-vietnamese.jpg" },
{ dish_name:"Chao Ga (Vietnamese Rice Porridge)", state:"Vietnam", cuisine:"Vietnamese", category:"Soups", difficulty_level:"Easy", prep_time_minutes:10, cook_time_minutes:60, total_time_minutes:70, servings:4, short_description:"Vietnam's healing rice porridge — soft rice simmered with chicken in a fragrant broth topped with ginger, spring onion and crispy shallots. The Vietnamese answer to congee.", ingredients:[{name:"Jasmine rice",quantity:"150",unit:"g"},{name:"Chicken pieces",quantity:"400",unit:"g"},{name:"Ginger",quantity:"30",unit:"g"},{name:"Spring onion",quantity:"4",unit:"stalks"},{name:"Fish sauce",quantity:"2",unit:"tbsp"},{name:"Salt",quantity:"0.5",unit:"tsp"},{name:"White pepper",quantity:"1",unit:"tsp"},{name:"Fried shallots",quantity:"3",unit:"tbsp"},{name:"Lime",quantity:"2",unit:"pieces"},{name:"Fresh coriander",quantity:"1",unit:"bunch"}], preparation_steps:["Simmer chicken with ginger until tender. Remove and shred.","Add rice to broth.","Cook on low heat 45 minutes until rice is completely soft.","Stir regularly — porridge should be silky, not gluey.","Return chicken to porridge.","Season with fish sauce and salt.","Serve topped with ginger strips, spring onion, fried shallots and coriander.","Squeeze lime and add white pepper."], chef_notes:"Chao should be silky smooth with a flowing consistency. Keep stirring as the rice cooks — it sticks to the bottom. Toppings are essential, not optional.", serving_suggestions:"Serve as a healing breakfast or light meal. Essential when sick.", nutrition_estimate:{calories:"265",protein_g:"18",carbohydrates_g:"38",fat_g:"5"}, tags:["Rice Porridge","Healing","Breakfast","Vietnamese"], img:"/images/vietnamese/soups/chao-ga-vietnamese-rice-porridge-vietnamese.jpg" },
{ dish_name:"Lau (Vietnamese Hot Pot)", state:"Vietnam", cuisine:"Vietnamese", category:"Soups", difficulty_level:"Medium", prep_time_minutes:30, cook_time_minutes:30, total_time_minutes:60, servings:4, short_description:"Vietnam's communal hot pot — a fragrant lemongrass and coconut milk broth at the table with seafood, meat and vegetables cooked communally. A festive Vietnamese tradition.", ingredients:[{name:"Lemongrass",quantity:"4",unit:"stalks"},{name:"Coconut milk",quantity:"200",unit:"ml"},{name:"Chicken stock",quantity:"1",unit:"litre"},{name:"Mixed seafood",quantity:"400",unit:"g"},{name:"Pork or beef slices",quantity:"300",unit:"g"},{name:"Tofu",quantity:"200",unit:"g"},{name:"Vegetables assorted",quantity:"400",unit:"g"},{name:"Rice noodles",quantity:"300",unit:"g"},{name:"Turmeric",quantity:"1",unit:"tsp"},{name:"Fish sauce",quantity:"3",unit:"tbsp"}], preparation_steps:["Make broth: simmer lemongrass in stock 20 minutes.","Add coconut milk and turmeric.","Season with fish sauce.","Set up portable burner at table.","Arrange all raw ingredients on platters around pot.","Bring broth to simmer at table.","Cook ingredients individually in broth.","Serve with dipping sauces and herbs."], chef_notes:"Vietnamese lau differs from Chinese hot pot in its use of lemongrass and coconut milk. The broth becomes increasingly flavourful as cooking progresses.", serving_suggestions:"Set up at the table communally. Serve with rice noodles, herbs and dipping sauces.", nutrition_estimate:{calories:"345",protein_g:"28",carbohydrates_g:"24",fat_g:"14"}, tags:["Hot Pot","Communal","Festive","Vietnamese"], img:"/images/vietnamese/soups/lau-vietnamese-hot-pot-vietnamese.jpg" },
{ dish_name:"Bun Rieu (Tomato Crab Noodle Soup)", state:"Vietnam", cuisine:"Vietnamese", category:"Soups", difficulty_level:"Hard", prep_time_minutes:30, cook_time_minutes:60, total_time_minutes:90, servings:4, short_description:"A uniquely Vietnamese tomato-based crab noodle soup with fluffy crab and tofu dumplings floating in a tangy tomato broth — deeply flavourful and unlike any other soup.", ingredients:[{name:"River crab or crab paste",quantity:"300",unit:"g"},{name:"Tomatoes",quantity:"4",unit:"large"},{name:"Firm tofu",quantity:"200",unit:"g"},{name:"Pork ribs",quantity:"300",unit:"g"},{name:"Shrimp paste",quantity:"1",unit:"tbsp"},{name:"Rice vermicelli",quantity:"300",unit:"g"},{name:"Tamarind",quantity:"2",unit:"tbsp"},{name:"Fish sauce",quantity:"3",unit:"tbsp"},{name:"Spring onion",quantity:"4",unit:"stalks"},{name:"Fried tofu",quantity:"150",unit:"g"}], preparation_steps:["Simmer pork ribs to make broth.","Blend crab with water and strain. Reserve solid crab paste.","Heat crab liquid gently — curd-like crab cake forms on surface.","Fry tomatoes in oil until soft. Add to broth.","Add tamarind and fish sauce.","Carefully ladle crab cake into broth.","Add fried tofu.","Serve over vermicelli topped with spring onion and herbs."], chef_notes:"The floating crab dumplings form naturally when crab liquid is heated — they must be scooped gently to keep them intact. Bun rieu is one of Vietnam's most complex soups.", serving_suggestions:"Serve with banana blossom, bean sprouts, lime and shrimp paste.", nutrition_estimate:{calories:"345",protein_g:"24",carbohydrates_g:"40",fat_g:"10"}, tags:["Crab","Tomato","Complex","Vietnamese"], img:"/images/vietnamese/soups/bun-rieu-tomato-crab-noodle-soup-vietnamese.jpg" },
{ dish_name:"Banh Canh (Thick Noodle Soup)", state:"Vietnam", cuisine:"Vietnamese", category:"Soups", difficulty_level:"Medium", prep_time_minutes:20, cook_time_minutes:60, total_time_minutes:80, servings:4, short_description:"A comforting Vietnamese soup with thick, chewy tapioca noodles in a clear pork broth — the Vietnamese equivalent of udon in its satisfying heartiness.", ingredients:[{name:"Pork bones",quantity:"600",unit:"g"},{name:"Banh canh noodles (thick tapioca)",quantity:"400",unit:"g"},{name:"Pork leg",quantity:"300",unit:"g"},{name:"Fish sauce",quantity:"3",unit:"tbsp"},{name:"Shallots",quantity:"4",unit:"pieces"},{name:"Ginger",quantity:"20",unit:"g"},{name:"Spring onion",quantity:"4",unit:"stalks"},{name:"Fried shallots",quantity:"3",unit:"tbsp"},{name:"White pepper",quantity:"1",unit:"tsp"}], preparation_steps:["Blanch pork bones. Cover with fresh water and simmer 1 hour.","Add charred shallots and ginger.","Add pork leg. Cook 30 minutes.","Remove pork leg, slice thinly.","Season broth with fish sauce and salt.","Cook thick noodles separately until tender.","Place noodles in bowls with pork slices.","Ladle hot broth over. Top with fried shallots and pepper."], chef_notes:"Banh canh noodles are much thicker and chewier than other Vietnamese noodles — their texture is the star of this dish. Do not overcook or they become mushy.", serving_suggestions:"Serve with lime, chilli and extra fish sauce on the side.", nutrition_estimate:{calories:"365",protein_g:"22",carbohydrates_g:"52",fat_g:"8"}, tags:["Thick Noodles","Comfort","Vietnamese","Hearty"], img:"/images/vietnamese/soups/banh-canh-thick-noodle-soup-vietnamese.jpg" },
// ── SALADS ──────────────────────────────────────────────────────────────────
{ dish_name:"Goi Ga (Vietnamese Chicken Salad)", state:"Vietnam", cuisine:"Vietnamese", category:"Salads", difficulty_level:"Easy", prep_time_minutes:25, cook_time_minutes:10, total_time_minutes:35, servings:4, short_description:"A refreshing Vietnamese salad of poached chicken with cabbage, mint, fried shallots and a tangy lime dressing — light, fragrant and utterly satisfying.", ingredients:[{name:"Chicken breast",quantity:"400",unit:"g"},{name:"Cabbage",quantity:"300",unit:"g"},{name:"Carrot",quantity:"1",unit:"large"},{name:"Fresh mint",quantity:"1",unit:"bunch"},{name:"Vietnamese coriander",quantity:"1",unit:"bunch"},{name:"Fried shallots",quantity:"4",unit:"tbsp"},{name:"Roasted peanuts",quantity:"4",unit:"tbsp"},{name:"Lime juice",quantity:"4",unit:"tbsp"},{name:"Fish sauce",quantity:"3",unit:"tbsp"},{name:"Sugar",quantity:"2",unit:"tbsp"},{name:"Chilli",quantity:"2",unit:"pieces"}], preparation_steps:["Poach chicken breast until just cooked. Cool and shred finely by hand.","Shred cabbage very finely. Julienne carrot.","Make dressing: lime juice, fish sauce, sugar and chilli.","Combine chicken, cabbage and carrot.","Pour dressing and toss well.","Add mint and Vietnamese coriander.","Top with fried shallots and peanuts.","Serve immediately."], chef_notes:"Hand-shredding chicken creates better texture for salads than knife-cutting. Vietnamese coriander (rau ram) has a unique lemony pepper flavour essential for authentic goi ga.", serving_suggestions:"Serve immediately as a starter or light meal.", nutrition_estimate:{calories:"245",protein_g:"26",carbohydrates_g:"16",fat_g:"8"}, tags:["Chicken Salad","Refreshing","Herbs","Vietnamese"], img:"/images/vietnamese/salads/goi-ga-vietnamese-chicken-salad-vietnamese.jpg" },
{ dish_name:"Goi Du Du (Green Papaya Salad)", state:"Vietnam", cuisine:"Vietnamese", category:"Salads", difficulty_level:"Easy", prep_time_minutes:20, cook_time_minutes:10, total_time_minutes:30, servings:4, short_description:"Vietnam's version of green papaya salad — shredded unripe papaya with beef jerky, basil and a tangy lime dressing. Lighter and more herbaceous than the Thai version.", ingredients:[{name:"Green papaya",quantity:"400",unit:"g"},{name:"Beef jerky (kho bo)",quantity:"100",unit:"g"},{name:"Carrot",quantity:"1",unit:"medium"},{name:"Fresh basil",quantity:"1",unit:"bunch"},{name:"Roasted peanuts",quantity:"4",unit:"tbsp"},{name:"Lime juice",quantity:"4",unit:"tbsp"},{name:"Fish sauce",quantity:"3",unit:"tbsp"},{name:"Sugar",quantity:"2",unit:"tbsp"},{name:"Garlic",quantity:"2",unit:"cloves"},{name:"Bird's eye chilli",quantity:"2",unit:"pieces"}], preparation_steps:["Peel and shred papaya into thin strips.","Julienne carrot.","Shred beef jerky into strips.","Make dressing: lime juice, fish sauce, sugar, garlic and chilli.","Toss papaya and carrot with dressing.","Add beef jerky and basil.","Top with peanuts.","Serve immediately."], chef_notes:"Vietnamese green papaya salad uses beef jerky instead of dried shrimp, giving it a meatier, different flavour than Thai som tam. The papaya should be firm and unripe.", serving_suggestions:"Serve immediately as a starter. Best eaten fresh before papaya wilts.", nutrition_estimate:{calories:"185",protein_g:"10",carbohydrates_g:"22",fat_g:"7"}, tags:["Green Papaya","Beef Jerky","Refreshing","Vietnamese"], img:"/images/vietnamese/salads/goi-du-du-green-papaya-salad-vietnamese.jpg" },
{ dish_name:"Goi Tom (Prawn Salad)", state:"Vietnam", cuisine:"Vietnamese", category:"Salads", difficulty_level:"Easy", prep_time_minutes:20, cook_time_minutes:5, total_time_minutes:25, servings:4, short_description:"A vibrant Vietnamese prawn salad with fresh herbs, pineapple and crispy shallots in a tangy lime dressing — tropical, fresh and deeply satisfying.", ingredients:[{name:"Cooked prawns",quantity:"300",unit:"g"},{name:"Pineapple",quantity:"150",unit:"g"},{name:"Cucumber",quantity:"1",unit:"large"},{name:"Shallots",quantity:"4",unit:"pieces"},{name:"Fresh mint",quantity:"1",unit:"bunch"},{name:"Coriander",quantity:"1",unit:"bunch"},{name:"Fried shallots",quantity:"3",unit:"tbsp"},{name:"Roasted peanuts",quantity:"3",unit:"tbsp"},{name:"Lime juice",quantity:"4",unit:"tbsp"},{name:"Fish sauce",quantity:"2",unit:"tbsp"},{name:"Sugar",quantity:"1",unit:"tbsp"}], preparation_steps:["Peel and devein prawns. Halve lengthwise.","Dice pineapple. Slice cucumber thinly.","Slice shallots thinly.","Make dressing: lime juice, fish sauce and sugar.","Combine prawns, pineapple, cucumber and shallots.","Add dressing and toss.","Add fresh herbs and toss gently.","Top with fried shallots and peanuts."], chef_notes:"Pineapple adds natural sweetness and acidity that complements prawns beautifully. Use fresh pineapple only — canned pineapple is too sweet and soft.", serving_suggestions:"Serve as a refreshing starter or light lunch.", nutrition_estimate:{calories:"185",protein_g:"18",carbohydrates_g:"18",fat_g:"5"}, tags:["Prawn","Pineapple","Tropical","Vietnamese"], img:"/images/vietnamese/salads/goi-tom-prawn-salad-vietnamese.jpg" },
{ dish_name:"Goi Cuon Chay (Vegetarian Spring Roll Salad)", state:"Vietnam", cuisine:"Vietnamese", category:"Salads", difficulty_level:"Easy", prep_time_minutes:25, cook_time_minutes:0, total_time_minutes:25, servings:4, short_description:"A deconstructed version of Vietnamese fresh spring rolls as a salad — all the fresh ingredients without the wrapping, dressed with a tangy herb dressing.", ingredients:[{name:"Rice vermicelli",quantity:"150",unit:"g"},{name:"Lettuce",quantity:"200",unit:"g"},{name:"Cucumber",quantity:"1",unit:"large"},{name:"Carrot",quantity:"1",unit:"medium"},{name:"Fresh mint",quantity:"1",unit:"bunch"},{name:"Bean sprouts",quantity:"150",unit:"g"},{name:"Tofu",quantity:"200",unit:"g"},{name:"Lime juice",quantity:"4",unit:"tbsp"},{name:"Soy sauce",quantity:"2",unit:"tbsp"},{name:"Sugar",quantity:"1",unit:"tbsp"},{name:"Roasted peanuts",quantity:"4",unit:"tbsp"}], preparation_steps:["Cook and cool vermicelli.","Pan-fry tofu until golden. Cool and slice.","Shred lettuce. Julienne cucumber and carrot.","Make dressing: lime juice, soy sauce and sugar.","Combine noodles, lettuce, cucumber, carrot and sprouts.","Add tofu and fresh herbs.","Dress and toss well.","Top with peanuts."], chef_notes:"This is a vegan-friendly Vietnamese salad with all the flavours of fresh spring rolls. The herbs are the key — use generous amounts.", serving_suggestions:"Serve as a light vegetarian lunch or starter.", nutrition_estimate:{calories:"225",protein_g:"10",carbohydrates_g:"32",fat_g:"7"}, tags:["Vegetarian","Fresh","Spring Roll","Vietnamese"], img:"/images/vietnamese/salads/goi-cuon-chay-vegetarian-spring-roll-salad-vietnamese.jpg" },
{ dish_name:"Nham (Vietnamese Fermented Pork Roll Salad)", state:"Vietnam", cuisine:"Vietnamese", category:"Salads", difficulty_level:"Medium", prep_time_minutes:30, cook_time_minutes:0, total_time_minutes:30, servings:4, short_description:"A southern Vietnamese fresh salad with nem chua fermented pork, crispy vegetables and roasted peanuts — tangy, complex and utterly unique.", ingredients:[{name:"Nem chua (fermented pork)",quantity:"200",unit:"g"},{name:"Cabbage",quantity:"200",unit:"g"},{name:"Carrot",quantity:"1",unit:"medium"},{name:"Bean sprouts",quantity:"100",unit:"g"},{name:"Fresh herbs",quantity:"1",unit:"bunch"},{name:"Roasted peanuts",quantity:"4",unit:"tbsp"},{name:"Lime juice",quantity:"3",unit:"tbsp"},{name:"Fish sauce",quantity:"2",unit:"tbsp"},{name:"Chilli",quantity:"2",unit:"pieces"},{name:"Garlic",quantity:"2",unit:"cloves"}], preparation_steps:["Slice nem chua into thin rounds.","Shred cabbage finely. Julienne carrot.","Make dressing: lime, fish sauce, garlic and chilli.","Combine nem chua with vegetables and sprouts.","Toss with dressing.","Add fresh herbs.","Top with peanuts.","Serve immediately."], chef_notes:"Nem chua brings a unique sour-savoury flavour from fermentation. If unavailable, substitute with prawn crackers or roasted pork. The fermented flavour is what makes this salad distinctive.", serving_suggestions:"Serve as an appetiser or alongside rice.", nutrition_estimate:{calories:"205",protein_g:"14",carbohydrates_g:"16",fat_g:"10"}, tags:["Fermented Pork","Southern Vietnam","Unique","Sour"], img:"/images/vietnamese/salads/nham-vietnamese-fermented-pork-roll-salad-vietnamese.jpg" },
{ dish_name:"Rau Muong Xao Toi (Water Spinach with Garlic)", state:"Vietnam", cuisine:"Vietnamese", category:"Salads", difficulty_level:"Easy", prep_time_minutes:5, cook_time_minutes:5, total_time_minutes:10, servings:4, short_description:"Vietnam's most beloved green vegetable dish — morning glory stir-fried with loads of garlic and fish sauce until wilted and fragrant. A staple at every Vietnamese table.", ingredients:[{name:"Water spinach (rau muong)",quantity:"500",unit:"g"},{name:"Garlic",quantity:"6",unit:"cloves"},{name:"Fish sauce",quantity:"2",unit:"tbsp"},{name:"Oyster sauce",quantity:"1",unit:"tbsp"},{name:"Oil",quantity:"3",unit:"tbsp"},{name:"Chilli",quantity:"2",unit:"pieces"}], preparation_steps:["Trim water spinach into 10cm pieces.","Smash garlic roughly — do not mince.","Heat wok until smoking hot.","Add oil and garlic. Fry 30 seconds.","Add water spinach all at once.","Stir-fry rapidly over highest heat 2 minutes.","Season with fish sauce and oyster sauce.","Serve immediately — it wilts quickly."], chef_notes:"Maximum heat is essential — water spinach must be cooked fast. It turns slimy if cooked too slowly. The garlic should be golden and fragrant.", serving_suggestions:"Serve immediately as a side dish with rice and other Vietnamese dishes.", nutrition_estimate:{calories:"85",protein_g:"3",carbohydrates_g:"6",fat_g:"6"}, tags:["Water Spinach","Garlic","Quick","Vietnamese Staple"], img:"/images/vietnamese/salads/rau-muong-xao-toi-water-spinach-garlic-vietnamese.jpg" },
{ dish_name:"Goi Xoai (Green Mango Salad)", state:"Vietnam", cuisine:"Vietnamese", category:"Salads", difficulty_level:"Easy", prep_time_minutes:20, cook_time_minutes:5, total_time_minutes:25, servings:4, short_description:"A vibrant Vietnamese green mango salad with dried beef, fresh herbs and roasted peanuts — tangy, sweet, salty and crunchy all at once.", ingredients:[{name:"Green mango",quantity:"3",unit:"medium"},{name:"Dried beef (bo kho)",quantity:"100",unit:"g"},{name:"Shallots",quantity:"3",unit:"pieces"},{name:"Roasted peanuts",quantity:"4",unit:"tbsp"},{name:"Fresh mint",quantity:"1",unit:"bunch"},{name:"Coriander",quantity:"1",unit:"bunch"},{name:"Lime juice",quantity:"3",unit:"tbsp"},{name:"Fish sauce",quantity:"2",unit:"tbsp"},{name:"Sugar",quantity:"2",unit:"tbsp"},{name:"Chilli",quantity:"2",unit:"pieces"}], preparation_steps:["Peel and shred green mango into thin strips.","Shred dried beef.","Slice shallots thinly.","Make dressing: lime juice, fish sauce, sugar and chilli.","Toss mango, beef and shallots with dressing.","Add fresh herbs and toss.","Top with peanuts.","Serve immediately."], chef_notes:"The mango must be unripe and firm — ripe mango is too soft and sweet. Dried beef adds a chewy, deeply flavoured contrast to the fresh mango.", serving_suggestions:"Serve as a starter or snack with prawn crackers.", nutrition_estimate:{calories:"165",protein_g:"8",carbohydrates_g:"22",fat_g:"6"}, tags:["Green Mango","Dried Beef","Tangy","Vietnamese"], img:"/images/vietnamese/salads/goi-xoai-green-mango-salad-vietnamese.jpg" },
{ dish_name:"Goi Bap Cai (Cabbage Prawn Salad)", state:"Vietnam", cuisine:"Vietnamese", category:"Salads", difficulty_level:"Easy", prep_time_minutes:20, cook_time_minutes:5, total_time_minutes:25, servings:4, short_description:"A crunchy Vietnamese cabbage salad with prawns and crispy shallots — simple, refreshing and the perfect accompaniment to any Vietnamese meal.", ingredients:[{name:"Cabbage",quantity:"400",unit:"g"},{name:"Cooked prawns",quantity:"200",unit:"g"},{name:"Carrot",quantity:"1",unit:"medium"},{name:"Fresh mint",quantity:"1",unit:"bunch"},{name:"Fried shallots",quantity:"4",unit:"tbsp"},{name:"Roasted peanuts",quantity:"3",unit:"tbsp"},{name:"Lime juice",quantity:"4",unit:"tbsp"},{name:"Fish sauce",quantity:"3",unit:"tbsp"},{name:"Sugar",quantity:"2",unit:"tbsp"},{name:"Chilli",quantity:"2",unit:"pieces"}], preparation_steps:["Shred cabbage very finely.","Julienne carrot.","Make dressing: lime, fish sauce, sugar and chilli.","Toss cabbage and carrot with dressing.","Add prawns and mint.","Top with fried shallots and peanuts.","Serve immediately."], chef_notes:"Finely shredded cabbage is key — thick pieces make the salad heavy. The fried shallots add essential crunch and aroma.", serving_suggestions:"Serve as a side salad or starter at any Vietnamese meal.", nutrition_estimate:{calories:"165",protein_g:"14",carbohydrates_g:"16",fat_g:"5"}, tags:["Cabbage","Prawn","Crunchy","Vietnamese"], img:"/images/vietnamese/salads/goi-bap-cai-cabbage-prawn-salad-vietnamese.jpg" },
{ dish_name:"Goi Ngo Sen (Lotus Stem Salad)", state:"Vietnam", cuisine:"Vietnamese", category:"Salads", difficulty_level:"Medium", prep_time_minutes:25, cook_time_minutes:5, total_time_minutes:30, servings:4, short_description:"An elegant Vietnamese salad of crunchy lotus stems with prawns and pork, dressed in a fragrant lime sauce — one of Vietnam's most beautiful and unique salads.", ingredients:[{name:"Lotus stems",quantity:"300",unit:"g"},{name:"Cooked prawns",quantity:"150",unit:"g"},{name:"Cooked pork belly",quantity:"150",unit:"g"},{name:"Roasted peanuts",quantity:"4",unit:"tbsp"},{name:"Vietnamese coriander",quantity:"1",unit:"bunch"},{name:"Fried shallots",quantity:"3",unit:"tbsp"},{name:"Lime juice",quantity:"4",unit:"tbsp"},{name:"Fish sauce",quantity:"3",unit:"tbsp"},{name:"Sugar",quantity:"2",unit:"tbsp"},{name:"Chilli",quantity:"2",unit:"pieces"}], preparation_steps:["Peel lotus stems and cut into 5cm pieces.","Soak in acidulated water to prevent browning.","Blanch briefly — 1 minute. Keep crunchy.","Drain and cool.","Slice pork belly thinly.","Make dressing: lime juice, fish sauce, sugar and chilli.","Combine lotus stems, prawns and pork.","Dress and toss. Add Vietnamese coriander.","Top with fried shallots and peanuts."], chef_notes:"Lotus stems have a unique hollow, crunchy texture and mild flavour. They must be soaked in acidulated water immediately after cutting to prevent browning.", serving_suggestions:"Serve as an elegant starter showing off Vietnamese culinary diversity.", nutrition_estimate:{calories:"205",protein_g:"16",carbohydrates_g:"16",fat_g:"8"}, tags:["Lotus Stem","Elegant","Unique","Vietnamese"], img:"/images/vietnamese/salads/goi-ngo-sen-lotus-stem-salad-vietnamese.jpg" },
// ── MAIN COURSES ────────────────────────────────────────────────────────────
{ dish_name:"Banh Mi Sandwich", state:"Vietnam", cuisine:"Vietnamese", category:"Main Courses", difficulty_level:"Easy", prep_time_minutes:20, cook_time_minutes:10, total_time_minutes:30, servings:4, short_description:"The world's greatest sandwich — crispy baguette with pate, cold cuts, pickled vegetables and fresh herbs. Vietnam's most internationally famous street food.", ingredients:[{name:"Vietnamese baguette",quantity:"4",unit:"pieces"},{name:"Pork pate",quantity:"100",unit:"g"},{name:"Cha lua pork sausage",quantity:"200",unit:"g"},{name:"Pickled daikon and carrot",quantity:"200",unit:"g"},{name:"Cucumber",quantity:"1",unit:"medium"},{name:"Coriander",quantity:"1",unit:"bunch"},{name:"Chilli",quantity:"4",unit:"pieces"},{name:"Mayonnaise",quantity:"4",unit:"tbsp"},{name:"Soy sauce",quantity:"1",unit:"tbsp"},{name:"Black pepper",quantity:"0.5",unit:"tsp"}], preparation_steps:["Quick-pickle daikon and carrot if not ready.","Warm baguette until exterior is crispy.","Spread pate on bottom half, mayo on top.","Layer with cha lua slices.","Add pickled vegetables and cucumber.","Add coriander sprigs and chilli slices.","Season with black pepper.","Press together and wrap in paper."], chef_notes:"The Vietnamese baguette is uniquely light and airy inside with a thin crispy shell. Use within minutes of baking for authentic banh mi experience.", serving_suggestions:"Wrap in paper and eat immediately on the go, street food style.", nutrition_estimate:{calories:"385",protein_g:"18",carbohydrates_g:"48",fat_g:"14"}, tags:["Sandwich","Street Food","Fusion","Iconic"], img:"/images/vietnamese/main-courses/banh-mi-sandwich-vietnamese.jpg" },
{ dish_name:"Bo Luc Lac (Shaking Beef)", state:"Vietnam", cuisine:"Vietnamese", category:"Main Courses", difficulty_level:"Easy", prep_time_minutes:20, cook_time_minutes:10, total_time_minutes:30, servings:4, short_description:"Vietnam's most celebrated beef dish — tender cubes of beef shaken in a screaming hot wok with garlic and butter, served on watercress with lime-pepper dipping sauce.", ingredients:[{name:"Beef sirloin or tenderloin",quantity:"500",unit:"g"},{name:"Garlic",quantity:"6",unit:"cloves"},{name:"Butter",quantity:"2",unit:"tbsp"},{name:"Soy sauce",quantity:"3",unit:"tbsp"},{name:"Oyster sauce",quantity:"2",unit:"tbsp"},{name:"Sugar",quantity:"1",unit:"tbsp"},{name:"Watercress or lettuce",quantity:"200",unit:"g"},{name:"Tomatoes",quantity:"2",unit:"medium"},{name:"Lime juice",quantity:"3",unit:"tbsp"},{name:"Black pepper",quantity:"2",unit:"tsp"},{name:"Red onion",quantity:"1",unit:"medium"}], preparation_steps:["Cut beef into 2cm cubes. Marinate with soy sauce, oyster sauce and sugar.","Heat wok until smoking hot.","Add butter and beef. Shake the wok vigorously — this is the 'luc lac' technique.","Cook 2 minutes only for medium-rare.","Add garlic in last 30 seconds.","Make dipping sauce: lime juice and black pepper.","Arrange watercress on plate with tomatoes.","Pile beef on top. Serve with lime-pepper sauce."], chef_notes:"The 'shaking' technique keeps the beef moving constantly in the hot wok — this creates even caramelisation without overcooking. Beef should be medium-rare inside.", serving_suggestions:"Serve on watercress with rice. Dip each piece in lime-pepper sauce.", nutrition_estimate:{calories:"345",protein_g:"32",carbohydrates_g:"10",fat_g:"18"}, tags:["Beef","Shaking Wok","French-Vietnamese","Butter"], img:"/images/vietnamese/main-courses/bo-luc-lac-shaking-beef-vietnamese.jpg" },
{ dish_name:"Ca Kho To (Caramelised Fish in Claypot)", state:"Vietnam", cuisine:"Vietnamese", category:"Main Courses", difficulty_level:"Medium", prep_time_minutes:15, cook_time_minutes:45, total_time_minutes:60, servings:4, short_description:"Vietnam's iconic claypot fish — catfish caramelised in coconut water with fish sauce, ginger and chilli until the sauce is dark, thick and sticky-sweet.", ingredients:[{name:"Catfish or salmon",quantity:"600",unit:"g"},{name:"Coconut water",quantity:"300",unit:"ml"},{name:"Fish sauce",quantity:"4",unit:"tbsp"},{name:"Sugar",quantity:"3",unit:"tbsp"},{name:"Ginger",quantity:"30",unit:"g"},{name:"Garlic",quantity:"4",unit:"cloves"},{name:"Shallots",quantity:"3",unit:"pieces"},{name:"Bird's eye chilli",quantity:"3",unit:"pieces"},{name:"Black pepper",quantity:"1",unit:"tsp"},{name:"Spring onion",quantity:"3",unit:"stalks"}], preparation_steps:["Cut fish into thick pieces.","Caramelise sugar in claypot or heavy pan until amber.","Add fish sauce carefully — it will spit.","Add coconut water, ginger, garlic, shallots and chilli.","Add fish pieces.","Simmer on very low heat 40 minutes.","Sauce should reduce to thick, dark glaze.","Garnish with spring onion and pepper.","Serve with plain white rice."], chef_notes:"The caramelisation is what gives ca kho to its signature dark colour and complex flavour. Low and slow is essential — rushing creates a burnt, bitter sauce.", serving_suggestions:"Serve with lots of plain white rice — the sauce is intensely flavoured.", nutrition_estimate:{calories:"285",protein_g:"28",carbohydrates_g:"20",fat_g:"10"}, tags:["Claypot","Caramelised Fish","Slow Cook","Vietnamese"], img:"/images/vietnamese/main-courses/ca-kho-to-caramelised-fish-claypot-vietnamese.jpg" },
{ dish_name:"Com Tam (Broken Rice with Pork)", state:"Vietnam", cuisine:"Vietnamese", category:"Main Courses", difficulty_level:"Medium", prep_time_minutes:30, cook_time_minutes:30, total_time_minutes:60, servings:4, short_description:"Saigon's most beloved street food dish — broken rice with grilled pork chop, shredded pork skin, steamed egg cake and all the essential accompaniments.", ingredients:[{name:"Broken jasmine rice",quantity:"400",unit:"g"},{name:"Pork chops",quantity:"4",unit:"pieces"},{name:"Lemongrass",quantity:"2",unit:"stalks"},{name:"Fish sauce",quantity:"4",unit:"tbsp"},{name:"Sugar",quantity:"2",unit:"tbsp"},{name:"Garlic",quantity:"4",unit:"cloves"},{name:"Eggs",quantity:"3",unit:"large"},{name:"Cucumber",quantity:"1",unit:"medium"},{name:"Spring onion",quantity:"4",unit:"stalks"},{name:"Nuoc cham sauce",quantity:"6",unit:"tbsp"}], preparation_steps:["Marinate pork chops with fish sauce, sugar, lemongrass and garlic overnight.","Grill pork chops on hot grill until charred.","Make bi: steam egg mixture in mould until set.","Cook broken rice — it has softer, stickier texture than regular rice.","Make nuoc cham dipping sauce.","Assemble plate: rice, pork chop, sliced egg cake, cucumber.","Top with fried shallots and spring onion oil.","Serve with nuoc cham."], chef_notes:"Broken rice (com tam) has a distinctly softer, stickier texture than whole grain rice — it absorbs nuoc cham beautifully. It was historically cheaper rice used by the poor.", serving_suggestions:"Serve on a plate with all components arranged separately. Drizzle nuoc cham.", nutrition_estimate:{calories:"525",protein_g:"34",carbohydrates_g:"62",fat_g:"16"}, tags:["Broken Rice","Saigon","Street Food","Iconic"], img:"/images/vietnamese/main-courses/com-tam-broken-rice-pork-vietnamese.jpg" },
{ dish_name:"Thit Kho Trung (Braised Pork and Eggs)", state:"Vietnam", cuisine:"Vietnamese", category:"Main Courses", difficulty_level:"Easy", prep_time_minutes:15, cook_time_minutes:60, total_time_minutes:75, servings:6, short_description:"Vietnam's ultimate Tet dish — pork belly and boiled eggs slowly braised in coconut water and fish sauce until the pork is fall-apart tender and the eggs are golden brown.", ingredients:[{name:"Pork belly",quantity:"800",unit:"g"},{name:"Hard boiled eggs",quantity:"6",unit:"pieces"},{name:"Coconut water",quantity:"400",unit:"ml"},{name:"Fish sauce",quantity:"4",unit:"tbsp"},{name:"Sugar",quantity:"3",unit:"tbsp"},{name:"Shallots",quantity:"4",unit:"pieces"},{name:"Garlic",quantity:"4",unit:"cloves"},{name:"Black pepper",quantity:"1",unit:"tsp"},{name:"Spring onion",quantity:"3",unit:"stalks"}], preparation_steps:["Cut pork belly into large chunks.","Caramelise sugar until amber. Add fish sauce.","Add pork and coat in caramel.","Add coconut water, shallots and garlic.","Simmer 30 minutes.","Add peeled hard boiled eggs.","Continue simmering 30 more minutes.","Eggs should turn golden brown, pork should be tender.","Season and serve with rice."], chef_notes:"Thit kho trung is the defining dish of Tet (Vietnamese New Year) — cooked in advance and eaten over the holiday. The coconut water adds natural sweetness. Never use regular water.", serving_suggestions:"Serve with plain rice and pickled mustard greens (dua chua).", nutrition_estimate:{calories:"485",protein_g:"28",carbohydrates_g:"14",fat_g:"36"}, tags:["Tet","Braised Pork","New Year","Vietnamese"], img:"/images/vietnamese/main-courses/thit-kho-trung-braised-pork-eggs-vietnamese.jpg" },
{ dish_name:"Ca Chien (Vietnamese Fried Fish)", state:"Vietnam", cuisine:"Vietnamese", category:"Main Courses", difficulty_level:"Easy", prep_time_minutes:15, cook_time_minutes:15, total_time_minutes:30, servings:4, short_description:"A whole fish fried until golden and crispy, served with ginger-fish sauce dipping sauce and fresh herbs — simple Vietnamese home cooking at its finest.", ingredients:[{name:"Whole fish",quantity:"800",unit:"g"},{name:"Ginger",quantity:"30",unit:"g"},{name:"Garlic",quantity:"4",unit:"cloves"},{name:"Fish sauce",quantity:"3",unit:"tbsp"},{name:"Lime juice",quantity:"2",unit:"tbsp"},{name:"Chilli",quantity:"2",unit:"pieces"},{name:"Turmeric",quantity:"0.5",unit:"tsp"},{name:"Oil for frying",quantity:"2",unit:"cups"},{name:"Fresh herbs",quantity:"1",unit:"bunch"},{name:"Cucumber",quantity:"1",unit:"medium"}], preparation_steps:["Score fish with deep diagonal cuts on both sides.","Rub inside and out with turmeric, salt and garlic.","Deep fry whole fish at 180°C until golden — 5-7 minutes per side.","Make dipping sauce: fish sauce, lime juice, ginger, chilli and garlic.","Arrange on platter with fresh herbs.","Serve dipping sauce alongside."], chef_notes:"Scoring the fish deeply allows the turmeric marinade to penetrate and ensures even cooking. The fish should be completely crispy all over.", serving_suggestions:"Serve with dipping sauce, fresh herbs, rice and canh soup.", nutrition_estimate:{calories:"265",protein_g:"32",carbohydrates_g:"4",fat_g:"14"}, tags:["Fried Fish","Simple","Home Cooking","Vietnamese"], img:"/images/vietnamese/main-courses/ca-chien-vietnamese-fried-fish-vietnamese.jpg" },
{ dish_name:"Bun Thit Nuong (BBQ Pork Noodle Bowl)", state:"Vietnam", cuisine:"Vietnamese", category:"Main Courses", difficulty_level:"Medium", prep_time_minutes:30, cook_time_minutes:20, total_time_minutes:50, servings:4, short_description:"A Southern Vietnamese noodle bowl with grilled lemongrass pork over cold rice vermicelli, fresh herbs, pickled vegetables and nuoc cham — the perfect meal in a bowl.", ingredients:[{name:"Pork shoulder",quantity:"500",unit:"g"},{name:"Lemongrass",quantity:"3",unit:"stalks"},{name:"Garlic",quantity:"5",unit:"cloves"},{name:"Fish sauce",quantity:"4",unit:"tbsp"},{name:"Sugar",quantity:"2",unit:"tbsp"},{name:"Rice vermicelli",quantity:"300",unit:"g"},{name:"Lettuce",quantity:"200",unit:"g"},{name:"Bean sprouts",quantity:"150",unit:"g"},{name:"Fresh herbs assorted",quantity:"1",unit:"bunch"},{name:"Pickled carrot and daikon",quantity:"150",unit:"g"},{name:"Roasted peanuts",quantity:"4",unit:"tbsp"}], preparation_steps:["Thinly slice pork. Marinate with lemongrass, garlic, fish sauce and sugar.","Grill pork over high heat until charred and fragrant.","Cook vermicelli, rinse under cold water.","Assemble bowls: vermicelli on bottom, then lettuce and herbs.","Top with grilled pork, pickled vegetables and peanuts.","Pour nuoc cham dressing generously over everything.","Toss before eating."], chef_notes:"The contrast of cold noodles, warm grilled pork and room temperature herbs with the tangy nuoc cham dressing is what makes this dish spectacular. Do not substitute cold noodles with hot.", serving_suggestions:"Serve with extra nuoc cham on the side. Toss everything together before eating.", nutrition_estimate:{calories:"445",protein_g:"30",carbohydrates_g:"52",fat_g:"14"}, tags:["BBQ Pork","Noodle Bowl","Southern Vietnam","Fresh"], img:"/images/vietnamese/main-courses/bun-thit-nuong-bbq-pork-noodle-bowl-vietnamese.jpg" },
{ dish_name:"Cha Ca La Vong (Turmeric Fish with Dill)", state:"Vietnam", cuisine:"Vietnamese", category:"Main Courses", difficulty_level:"Medium", prep_time_minutes:30, cook_time_minutes:15, total_time_minutes:45, servings:4, short_description:"Hanoi's most legendary restaurant dish — turmeric-marinated catfish sizzled in butter with dill and spring onion at the table, eaten with vermicelli and peanuts.", ingredients:[{name:"Catfish or firm white fish",quantity:"600",unit:"g"},{name:"Turmeric",quantity:"2",unit:"tsp"},{name:"Galangal",quantity:"20",unit:"g"},{name:"Fish sauce",quantity:"3",unit:"tbsp"},{name:"Shrimp paste",quantity:"1",unit:"tsp"},{name:"Fresh dill",quantity:"2",unit:"bunches"},{name:"Spring onion",quantity:"6",unit:"stalks"},{name:"Butter",quantity:"3",unit:"tbsp"},{name:"Vermicelli",quantity:"200",unit:"g"},{name:"Roasted peanuts",quantity:"4",unit:"tbsp"}], preparation_steps:["Marinate fish with turmeric, galangal, fish sauce and shrimp paste 1 hour.","Grill or pan-fry fish until golden.","Bring to table on a sizzling pan.","Add butter at the table.","Add huge handfuls of dill and spring onion — they cook briefly in the hot pan.","Serve with cold vermicelli, peanuts and nuoc cham.","Wrap fish and herbs in lettuce to eat."], chef_notes:"Cha ca La Vong is so beloved in Hanoi that the restaurant that created it has its own street named after it. The dill must be fresh and abundant — it is not a garnish but a main component.", serving_suggestions:"Serve sizzling at the table. Wrap in lettuce with noodles and peanuts.", nutrition_estimate:{calories:"345",protein_g:"32",carbohydrates_g:"22",fat_g:"14"}, tags:["Hanoi","Turmeric Fish","Dill","Legendary"], img:"/images/vietnamese/main-courses/cha-ca-la-vong-turmeric-fish-dill-vietnamese.jpg" },
{ dish_name:"Hu Tieu Nam Vang (Phnom Penh Noodle Soup)", state:"Vietnam", cuisine:"Vietnamese", category:"Main Courses", difficulty_level:"Medium", prep_time_minutes:20, cook_time_minutes:60, total_time_minutes:80, servings:4, short_description:"A clear, sweet pork broth with chewy tapioca noodles, pork, prawns and quail eggs — Southern Vietnam's beloved Cambodian-influenced noodle dish.", ingredients:[{name:"Pork bones",quantity:"500",unit:"g"},{name:"Dried squid",quantity:"30",unit:"g"},{name:"Daikon radish",quantity:"200",unit:"g"},{name:"Hu tieu noodles",quantity:"400",unit:"g"},{name:"Prawns",quantity:"200",unit:"g"},{name:"Sliced pork",quantity:"200",unit:"g"},{name:"Quail eggs",quantity:"8",unit:"pieces"},{name:"Fish sauce",quantity:"3",unit:"tbsp"},{name:"Sugar",quantity:"1",unit:"tbsp"},{name:"Fried garlic",quantity:"3",unit:"tbsp"}], preparation_steps:["Simmer pork bones with dried squid and daikon 1 hour.","Season with fish sauce and sugar.","Cook noodles separately.","Poach prawns and pork slices in broth briefly.","Boil quail eggs and peel.","Place noodles in bowls with toppings.","Ladle clear broth over.","Top with fried garlic, spring onion and white pepper."], chef_notes:"Dried squid in the broth adds a unique sweetness that defines hu tieu. The broth should be very clear and naturally sweet without being cloying.", serving_suggestions:"Serve with bean sprouts, lime, chilli and extra fish sauce.", nutrition_estimate:{calories:"365",protein_g:"26",carbohydrates_g:"48",fat_g:"8"}, tags:["Noodle Soup","Southern Vietnam","Clear Broth","Cambodian Influence"], img:"/images/vietnamese/main-courses/hu-tieu-nam-vang-phnom-penh-noodle-soup-vietnamese.jpg" },
{ dish_name:"Mi Quang (Turmeric Noodles)", state:"Vietnam", cuisine:"Vietnamese", category:"Main Courses", difficulty_level:"Medium", prep_time_minutes:30, cook_time_minutes:30, total_time_minutes:60, servings:4, short_description:"Central Vietnam's most beloved noodle dish — wide turmeric-yellow noodles with pork, prawns and a small amount of flavourful broth, topped with peanuts and sesame crackers.", ingredients:[{name:"Wide rice noodles",quantity:"400",unit:"g"},{name:"Pork ribs",quantity:"300",unit:"g"},{name:"Prawns",quantity:"200",unit:"g"},{name:"Turmeric",quantity:"2",unit:"tsp"},{name:"Shallots",quantity:"4",unit:"pieces"},{name:"Garlic",quantity:"4",unit:"cloves"},{name:"Fish sauce",quantity:"3",unit:"tbsp"},{name:"Roasted peanuts",quantity:"4",unit:"tbsp"},{name:"Sesame crackers",quantity:"4",unit:"pieces"},{name:"Fresh herbs",quantity:"1",unit:"bunch"}], preparation_steps:["Simmer pork ribs to make broth. Season with fish sauce.","Cook prawns. Fry shallots until golden.","Cook noodles with turmeric — they should turn yellow.","Add very small amount of broth to noodles — this is not a soup.","Arrange pork ribs and prawns on top.","Top with fried shallots, peanuts and herbs.","Place sesame cracker on side.","Add chilli and lime to taste."], chef_notes:"Mi quang uses minimal broth unlike pho — just enough to flavour the noodles. The sesame cracker added at serving is essential for authentic mi quang texture.", serving_suggestions:"Serve with sesame crackers, fresh herbs, lime and chilli.", nutrition_estimate:{calories:"425",protein_g:"26",carbohydrates_g:"58",fat_g:"12"}, tags:["Turmeric Noodles","Central Vietnam","Quang Nam","Unique"], img:"/images/vietnamese/main-courses/mi-quang-turmeric-noodles-vietnamese.jpg" },
// ── DESSERTS ────────────────────────────────────────────────────────────────
{ dish_name:"Che Ba Mau (Three Colour Dessert)", state:"Vietnam", cuisine:"Vietnamese", category:"Desserts", difficulty_level:"Easy", prep_time_minutes:20, cook_time_minutes:10, total_time_minutes:30, servings:4, short_description:"Vietnam's most colourful dessert — layers of green pandan jelly, yellow mung bean, red beans and coconut milk over shaved ice. Beautiful, refreshing and beloved.", ingredients:[{name:"Mung beans",quantity:"150",unit:"g"},{name:"Red beans",quantity:"100",unit:"g"},{name:"Green pandan jelly",quantity:"150",unit:"g"},{name:"Coconut milk",quantity:"400",unit:"ml"},{name:"Sugar",quantity:"80",unit:"g"},{name:"Salt",quantity:"0.5",unit:"tsp"},{name:"Shaved ice",quantity:"4",unit:"cups"},{name:"Pandan extract",quantity:"1",unit:"tsp"}], preparation_steps:["Cook mung beans with sugar until soft. Cool.","Cook red beans with sugar until tender. Cool.","Make pandan jelly and cut into cubes.","Warm coconut milk with salt and sugar.","Fill tall glasses with shaved ice.","Layer red beans, mung beans and pandan jelly over ice.","Pour warm coconut milk over.","Serve immediately."], chef_notes:"The three colours — red, yellow and green — are as important as the flavour. Layer them separately for visual impact. The contrast of cold ice and warm coconut milk is the magic.", serving_suggestions:"Serve in tall glasses over shaved ice. A Vietnamese street dessert staple.", nutrition_estimate:{calories:"285",protein_g:"6",carbohydrates_g:"52",fat_g:"8"}, tags:["Three Colour","Street Dessert","Coconut Milk","Vietnamese"], img:"/images/vietnamese/desserts/che-ba-mau-three-colour-dessert-vietnamese.jpg" },
{ dish_name:"Banh Flan (Vietnamese Crème Caramel)", state:"Vietnam", cuisine:"Vietnamese", category:"Desserts", difficulty_level:"Medium", prep_time_minutes:20, cook_time_minutes:40, total_time_minutes:240, servings:6, short_description:"Vietnam's beloved French-influenced crème caramel — richer and more eggy than the French version, often served over ice with black coffee poured over. A perfect fusion dessert.", ingredients:[{name:"Eggs",quantity:"4",unit:"large"},{name:"Egg yolks",quantity:"2",unit:"large"},{name:"Sweetened condensed milk",quantity:"200",unit:"ml"},{name:"Whole milk",quantity:"300",unit:"ml"},{name:"Sugar",quantity:"100",unit:"g"},{name:"Water",quantity:"2",unit:"tbsp"},{name:"Vanilla",quantity:"1",unit:"tsp"},{name:"Strong black coffee",quantity:"4",unit:"tbsp"}], preparation_steps:["Make caramel: cook sugar until amber. Add water carefully.","Pour into ramekins. Let set.","Beat eggs with condensed milk, regular milk and vanilla.","Strain mixture through fine sieve.","Pour over caramel in ramekins.","Steam or bake in water bath at 160°C for 40 minutes.","Cool and refrigerate 3 hours minimum.","Unmould and serve with black coffee poured over."], chef_notes:"Vietnamese banh flan uses condensed milk for extra richness. The black coffee poured over at serving is uniquely Vietnamese — it adds a bittersweet contrast.", serving_suggestions:"Unmould onto plates. Pour a shot of Vietnamese black coffee over each.", nutrition_estimate:{calories:"265",protein_g:"8",carbohydrates_g:"38",fat_g:"10"}, tags:["French Influence","Crème Caramel","Coffee","Vietnamese Dessert"], img:"/images/vietnamese/desserts/banh-flan-vietnamese-creme-caramel-vietnamese.jpg" },
{ dish_name:"Che Dau Xanh (Mung Bean Pudding)", state:"Vietnam", cuisine:"Vietnamese", category:"Desserts", difficulty_level:"Easy", prep_time_minutes:10, cook_time_minutes:40, total_time_minutes:50, servings:6, short_description:"Vietnam's most comforting dessert soup — soft mung beans in sweetened coconut milk with pandan fragrance. Simple, nourishing and deeply Vietnamese.", ingredients:[{name:"Split mung beans",quantity:"250",unit:"g"},{name:"Coconut milk",quantity:"300",unit:"ml"},{name:"Sugar",quantity:"80",unit:"g"},{name:"Pandan leaves",quantity:"3",unit:"pieces"},{name:"Salt",quantity:"0.5",unit:"tsp"},{name:"Tapioca pearls",quantity:"50",unit:"g"}], preparation_steps:["Soak mung beans 2 hours. Drain.","Cook mung beans with pandan leaves until very soft.","Remove pandan. Add sugar and salt.","Cook tapioca pearls separately until transparent.","Add tapioca to mung bean mixture.","Heat coconut milk gently. Pour over beans when serving.","Serve warm or chilled."], chef_notes:"Mung beans should be very soft and starting to break down into a creamy texture. The pandan leaves are essential for the fragrant character.", serving_suggestions:"Serve warm or cold depending on season.", nutrition_estimate:{calories:"245",protein_g:"8",carbohydrates_g:"44",fat_g:"6"}, tags:["Mung Bean","Coconut Milk","Comforting","Vietnamese"], img:"/images/vietnamese/desserts/che-dau-xanh-mung-bean-pudding-vietnamese.jpg" },
{ dish_name:"Banh Chuoi Nuong (Baked Banana Cake)", state:"Vietnam", cuisine:"Vietnamese", category:"Desserts", difficulty_level:"Easy", prep_time_minutes:15, cook_time_minutes:40, total_time_minutes:55, servings:8, short_description:"A fragrant Vietnamese banana cake baked with coconut milk and pandan — dense, moist and fragrant. A simple but completely addictive dessert.", ingredients:[{name:"Ripe bananas",quantity:"8",unit:"medium"},{name:"Coconut milk",quantity:"300",unit:"ml"},{name:"Sugar",quantity:"80",unit:"g"},{name:"Glutinous rice flour",quantity:"100",unit:"g"},{name:"Tapioca flour",quantity:"50",unit:"g"},{name:"Salt",quantity:"0.5",unit:"tsp"},{name:"Pandan extract",quantity:"1",unit:"tsp"},{name:"Sesame seeds",quantity:"2",unit:"tbsp"}], preparation_steps:["Mash bananas roughly — keep some texture.","Mix coconut milk, sugar, flours, salt and pandan extract.","Fold in mashed bananas.","Pour into greased baking dish.","Sprinkle sesame seeds on top.","Bake at 180°C for 35-40 minutes.","Cool before cutting — it firms as it cools.","Cut into squares."], chef_notes:"Use very ripe bananas — the sweeter and more spotted the better. The cake should be dense and slightly sticky, not fluffy like Western banana bread.", serving_suggestions:"Serve at room temperature cut into squares.", nutrition_estimate:{calories:"225",protein_g:"3",carbohydrates_g:"42",fat_g:"7"}, tags:["Banana","Baked","Coconut","Vietnamese Dessert"], img:"/images/vietnamese/desserts/banh-chuoi-nuong-baked-banana-cake-vietnamese.jpg" },
{ dish_name:"Sinh To Bo (Vietnamese Avocado Shake)", state:"Vietnam", cuisine:"Vietnamese", category:"Desserts", difficulty_level:"Easy", prep_time_minutes:10, cook_time_minutes:0, total_time_minutes:10, servings:2, short_description:"Vietnam's beloved avocado shake — blended with condensed milk and ice into a thick, creamy, sweet dessert drink. Vietnamese treat avocado as a dessert, not a savoury ingredient.", ingredients:[{name:"Ripe avocados",quantity:"2",unit:"large"},{name:"Sweetened condensed milk",quantity:"4",unit:"tbsp"},{name:"Whole milk",quantity:"100",unit:"ml"},{name:"Ice",quantity:"2",unit:"cups"},{name:"Sugar",quantity:"1",unit:"tbsp"}], preparation_steps:["Halve and scoop avocado flesh.","Blend avocado with condensed milk, milk and sugar.","Add ice and blend until smooth and thick.","Taste and adjust sweetness.","Pour into tall glasses.","Serve immediately with a thick straw."], chef_notes:"Vietnamese sinh to is much thicker than a Western smoothie — it should be spoonable. Use very ripe, buttery avocados for the richest flavour. Condensed milk is non-negotiable.", serving_suggestions:"Serve immediately in tall glasses. Do not delay — avocado oxidises quickly.", nutrition_estimate:{calories:"345",protein_g:"5",carbohydrates_g:"36",fat_g:"22"}, tags:["Avocado","Shake","Sweet","Vietnamese Dessert"], img:"/images/vietnamese/desserts/sinh-to-bo-vietnamese-avocado-shake-vietnamese.jpg" },
{ dish_name:"Banh Troi (Floating Rice Cakes)", state:"Vietnam", cuisine:"Vietnamese", category:"Desserts", difficulty_level:"Medium", prep_time_minutes:30, cook_time_minutes:15, total_time_minutes:45, servings:6, short_description:"White glutinous rice balls filled with palm sugar floating in ginger syrup — a traditional Vietnamese dessert eaten on Han Thuc (Cold Food Festival).", ingredients:[{name:"Glutinous rice flour",quantity:"300",unit:"g"},{name:"Palm sugar",quantity:"150",unit:"g"},{name:"Ginger",quantity:"50",unit:"g"},{name:"Sugar",quantity:"100",unit:"g"},{name:"Water",quantity:"400",unit:"ml"},{name:"Sesame seeds",quantity:"2",unit:"tbsp"},{name:"Salt",quantity:"0.25",unit:"tsp"}], preparation_steps:["Mix rice flour with warm water to smooth dough.","Break palm sugar into small pieces.","Wrap small portions of dough around palm sugar.","Roll into smooth balls.","Boil in water until they float, then 2 more minutes.","Make ginger syrup: simmer water, sugar and ginger slices.","Serve rice balls in warm ginger syrup.","Top with toasted sesame seeds."], chef_notes:"The balls should be perfectly smooth and round. They float when cooked — leave them for 2 more minutes after floating to ensure the palm sugar inside has melted.", serving_suggestions:"Serve warm in ginger syrup. Traditional on Han Thuc festival.", nutrition_estimate:{calories:"265",protein_g:"3",carbohydrates_g:"56",fat_g:"2"}, tags:["Rice Balls","Palm Sugar","Traditional","Festival"], img:"/images/vietnamese/desserts/banh-troi-floating-rice-cakes-vietnamese.jpg" },
{ dish_name:"Che Thai (Thai-Inspired Vietnamese Dessert)", state:"Vietnam", cuisine:"Vietnamese", category:"Desserts", difficulty_level:"Easy", prep_time_minutes:20, cook_time_minutes:10, total_time_minutes:30, servings:4, short_description:"A colourful Vietnamese dessert soup with mixed jellies, coconut cream, fruits and tapioca — refreshing, sweet and visually beautiful. Popular throughout South-East Asia.", ingredients:[{name:"Grass jelly",quantity:"150",unit:"g"},{name:"Coconut jelly",quantity:"150",unit:"g"},{name:"Jackfruit",quantity:"100",unit:"g"},{name:"Lychee",quantity:"12",unit:"pieces"},{name:"Coconut cream",quantity:"300",unit:"ml"},{name:"Sugar",quantity:"60",unit:"g"},{name:"Tapioca pearls",quantity:"50",unit:"g"},{name:"Crushed ice",quantity:"4",unit:"cups"},{name:"Pandan jelly",quantity:"100",unit:"g"}], preparation_steps:["Cook tapioca pearls until transparent. Cool.","Cut all jellies into cubes.","Prepare coconut cream with sugar and salt.","Fill large bowls with crushed ice.","Arrange jellies, jackfruit and lychee over ice.","Add tapioca pearls.","Pour coconut cream over everything.","Serve immediately."], chef_notes:"The variety of colours and textures is what makes che thai appealing. Use at least 4 different jellies for visual impact. Serve very cold.", serving_suggestions:"Serve in large bowls or glasses over crushed ice.", nutrition_estimate:{calories:"265",protein_g:"2",carbohydrates_g:"52",fat_g:"8"}, tags:["Mixed Dessert","Coconut","Colourful","Vietnamese"], img:"/images/vietnamese/desserts/che-thai-thai-inspired-vietnamese-dessert-vietnamese.jpg" },
{ dish_name:"Nuoc Cot Dua (Coconut Pudding)", state:"Vietnam", cuisine:"Vietnamese", category:"Desserts", difficulty_level:"Easy", prep_time_minutes:10, cook_time_minutes:15, total_time_minutes:25, servings:6, short_description:"A silky Vietnamese coconut pudding set with agar agar — delicate, fragrant and wobbly. Served chilled as a simple, elegant Vietnamese dessert.", ingredients:[{name:"Coconut milk",quantity:"600",unit:"ml"},{name:"Agar agar powder",quantity:"5",unit:"g"},{name:"Sugar",quantity:"80",unit:"g"},{name:"Salt",quantity:"0.25",unit:"tsp"},{name:"Pandan extract",quantity:"1",unit:"tsp"},{name:"Toasted coconut",quantity:"3",unit:"tbsp"}], preparation_steps:["Dissolve agar in 100ml cold coconut milk.","Heat remaining coconut milk with sugar and salt.","Add dissolved agar mixture. Stir well.","Add pandan extract.","Bring to simmer stirring constantly.","Pour into moulds or glasses.","Cool to room temperature then refrigerate 2 hours.","Unmould and top with toasted coconut."], chef_notes:"Agar sets firmer than gelatin and at room temperature — do not refrigerate before it sets naturally. The texture should be silky and wobbly.", serving_suggestions:"Serve chilled, unmoulded onto plates with toasted coconut.", nutrition_estimate:{calories:"185",protein_g:"2",carbohydrates_g:"28",fat_g:"9"}, tags:["Coconut Pudding","Agar","Silky","Vietnamese Dessert"], img:"/images/vietnamese/desserts/nuoc-cot-dua-coconut-pudding-vietnamese.jpg" },
{ dish_name:"Banh Pia (Vietnamese Mooncake)", state:"Vietnam", cuisine:"Vietnamese", category:"Desserts", difficulty_level:"Hard", prep_time_minutes:60, cook_time_minutes:30, total_time_minutes:90, servings:12, short_description:"A flaky, layered Vietnamese pastry from Soc Trang — spiral-layered dough filled with durian, mung bean or taro paste. A beloved Teochew-Vietnamese confection.", ingredients:[{name:"Plain flour",quantity:"300",unit:"g"},{name:"Lard or shortening",quantity:"150",unit:"g"},{name:"Mung bean paste",quantity:"400",unit:"g"},{name:"Salted egg yolks",quantity:"6",unit:"pieces"},{name:"Sugar",quantity:"60",unit:"g"},{name:"Water",quantity:"100",unit:"ml"},{name:"Egg yolk for wash",quantity:"2",unit:"pieces"},{name:"Sesame seeds",quantity:"2",unit:"tbsp"}], preparation_steps:["Make water dough: flour, lard and water.","Make oil dough: flour and lard only.","Wrap oil dough inside water dough. Roll and fold 3 times.","Roll into log and cut into portions.","Flatten each portion and fill with mung bean paste and egg yolk.","Seal and shape into round cakes.","Brush with egg wash. Sprinkle sesame seeds.","Bake at 180°C for 25 minutes until golden."], chef_notes:"The laminating technique (folding oil and water doughs together) creates the spiral, flaky layers. Lard is traditional and gives the most delicate layers — butter is a substitute.", serving_suggestions:"Serve with Chinese tea. Keeps for one week at room temperature.", nutrition_estimate:{calories:"285",protein_g:"6",carbohydrates_g:"36",fat_g:"14"}, tags:["Pastry","Layered","Mooncake","Vietnamese-Chinese"], img:"/images/vietnamese/desserts/banh-pia-vietnamese-mooncake-vietnamese.jpg" },
];

